#pragma once

// galimatron
#include "galimatron/translator_library/antlr_forward.hpp"

// generated by Antlr
#include "g_lexer.h"
#include "g_parser.h"


namespace galimatron::translator::parser
{

class state_t : public antlr4::BaseErrorListener
{
public:
    state_t(const content_t& content);

    state_t(const state_t&) = delete;
    state_t& operator=(const state_t&) = delete;

public:// state_t

    void do_production_parse();
    void do_test_string_parse();

    antlr_parse_tree_t* tree() const;
    antlr4::CommonTokenStream& token_stream() { return token_stream_; }

private:// antlr4::BaseErrorListener

    // we throw antlr4::ParseCancellationException,
    // because by default syntaxError() does not throw
    //
    virtual void syntaxError(
        antlr4::Recognizer* recognizer,
        antlr4::Token* offendingSymbol,
        size_t line,
        size_t charPositionInLine,
        const std::string& message,
        std::exception_ptr e
    ) override;

private:
    antlr4::ANTLRInputStream input_stream_;
    g_lexer lexer_;
    antlr4::CommonTokenStream token_stream_;
    g_parser parser_;
    antlr_parse_tree_t* tree_ = nullptr;
};

}// namespace galimatron::translator::parser
